schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/rfc-template-product-dev-team.json",
  "title": "Product-dev RFC",
  "type": "object",
  "required": ["rfc", "owner", "inputs", "decision", "supersession", "evidence", "review"],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "url": {"type": "string", "pattern": "^https://"},
    "text": {"type": "string", "minLength": 8}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "rfc": {
      "type": "object",
      "required": ["id", "title", "author", "shared_on"],
      "additionalProperties": false,
      "properties": {
        "id": {"type": "string", "pattern": "^RFC-[0-9]{3,}$"},
        "title": {"type": "string", "minLength": 8},
        "author": {"$ref": "#/definitions/handle"},
        "shared_on": {"$ref": "#/definitions/date"}
      }
    },
    "owner": {"$ref": "#/definitions/handle"},
    "inputs": {
      "type": "array",
      "minItems": 9,
      "allOf": [
        {"contains": {"properties": {"name": {"const": "problem"}}}},
        {"contains": {"properties": {"name": {"const": "options"}}}},
        {"contains": {"properties": {"name": {"const": "blast_radius"}}}},
        {"contains": {"properties": {"name": {"const": "rollback"}}}},
        {"contains": {"properties": {"name": {"const": "milestones"}}}},
        {"contains": {"properties": {"name": {"const": "status"}}}},
        {"contains": {"properties": {"name": {"const": "decided_on"}}}},
        {"contains": {"properties": {"name": {"const": "reviewers"}}}},
        {"contains": {"properties": {"name": {"const": "comment_deadline"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["name", "value"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "enum": ["problem", "options", "blast_radius", "rollback", "milestones", "status", "decided_on", "reviewers", "comment_deadline"]},
          "value": {}
        },
        "allOf": [
          {"if": {"properties": {"name": {"const": "problem"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["metric", "current_value", "target_value", "by_date", "statement"],
             "additionalProperties": false,
             "properties": {
               "metric": {"$ref": "#/definitions/text"},
               "current_value": {"type": "string", "minLength": 1, "pattern": "[0-9]"},
               "target_value": {"type": "string", "minLength": 1, "pattern": "[0-9]"},
               "by_date": {"$ref": "#/definitions/date"},
               "statement": {"type": "string", "minLength": 20, "pattern": "^(?![\\s\\S]*([Mm]igrate to|[Aa]dopt |[Ss]witch to|[Mm]ove to|[Nn]eed to use|[Rr]ewrite in))"}}}}}},
          {"if": {"properties": {"name": {"const": "options"}}},
           "then": {"properties": {"value": {
             "type": "array", "minItems": 2,
             "contains": {"properties": {"chosen": {"const": true}}},
             "items": {
               "type": "object",
               "required": ["name", "chosen"],
               "additionalProperties": false,
               "properties": {
                 "name": {"type": "string", "minLength": 4},
                 "chosen": {"type": "boolean"},
                 "rejection_reason": {"$ref": "#/definitions/text"}},
               "if": {"properties": {"chosen": {"const": false}}},
               "then": {"required": ["rejection_reason"]}}}}}},
          {"if": {"properties": {"name": {"const": "blast_radius"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["items", "schema_change", "public_api_change", "data_backfill", "third_party_change"],
             "additionalProperties": false,
             "properties": {
               "items": {
                 "type": "array", "minItems": 1,
                 "items": {
                   "type": "object",
                   "required": ["kind", "name", "owner"],
                   "additionalProperties": false,
                   "properties": {
                     "kind": {"type": "string", "enum": ["service", "data-store", "api", "scheduled-job", "user-segment"]},
                     "name": {"type": "string", "minLength": 2},
                     "owner": {"$ref": "#/definitions/handle"},
                     "count": {"type": "string", "minLength": 1, "pattern": "[0-9]"}},
                   "if": {"properties": {"kind": {"enum": ["api", "user-segment"]}}},
                   "then": {"required": ["count"]}}},
               "schema_change": {"type": "boolean"},
               "public_api_change": {"type": "boolean"},
               "data_backfill": {"type": "boolean"},
               "third_party_change": {"type": "boolean"}}}}}},
          {"if": {"properties": {"name": {"const": "rollback"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["mechanism", "execute_minutes", "executor", "staging_run", "points_of_no_return"],
             "additionalProperties": false,
             "properties": {
               "mechanism": {"type": "string", "enum": ["feature-flag-off", "revert-pr", "down-migration", "config-revert"]},
               "execute_minutes": {"type": "number", "minimum": 0},
               "executor": {"$ref": "#/definitions/handle"},
               "staging_run": {
                 "type": "object",
                 "required": ["exercised"],
                 "additionalProperties": false,
                 "properties": {
                   "exercised": {"type": "boolean"},
                   "url": {"$ref": "#/definitions/url"},
                   "reason": {"$ref": "#/definitions/text"}},
                 "if": {"properties": {"exercised": {"const": true}}},
                 "then": {"required": ["url"]},
                 "else": {"required": ["reason"]}},
               "points_of_no_return": {
                 "type": "array",
                 "items": {
                   "type": "object",
                   "required": ["step", "pre_check"],
                   "additionalProperties": false,
                   "properties": {"step": {"$ref": "#/definitions/text"}, "pre_check": {"$ref": "#/definitions/text"}}}}}}}}},
          {"if": {"properties": {"name": {"const": "milestones"}}},
           "then": {"properties": {"value": {
             "type": "array", "minItems": 2,
             "contains": {"properties": {"ship": {"const": true}}},
             "items": {
               "type": "object",
               "required": ["date", "increment", "ship"],
               "additionalProperties": false,
               "properties": {
                 "date": {"$ref": "#/definitions/date"},
                 "increment": {"type": "string", "minLength": 12, "pattern": "^(?!(design|implementation|build|testing|test|launch|done|qa)$)"},
                 "ship": {"type": "boolean"}}}}}}},
          {"if": {"properties": {"name": {"const": "status"}}},
           "then": {"properties": {"value": {"type": "string", "enum": ["proposed", "accepted", "rejected", "superseded"]}}}},
          {"if": {"properties": {"name": {"const": "decided_on"}}},
           "then": {"properties": {"value": {"$ref": "#/definitions/date"}}}},
          {"if": {"properties": {"name": {"const": "reviewers"}}},
           "then": {"properties": {"value": {
             "type": "array", "minItems": 1,
             "items": {
               "type": "object",
               "required": ["handle", "commented"],
               "additionalProperties": false,
               "properties": {
                 "handle": {"type": "string", "pattern": "^(?!(team|channel|everyone|all)[:@])[a-z-]+:[a-z0-9._-]+$"},
                 "commented": {"type": "boolean"}}}}}}},
          {"if": {"properties": {"name": {"const": "comment_deadline"}}},
           "then": {"properties": {"value": {"$ref": "#/definitions/date"}}}}
        ]
      }
    },
    "decision": {"type": "string", "minLength": 20, "pattern": "^[^.!?]+[.]?$"},
    "supersession": {
      "type": "object",
      "required": ["superseded_by", "supersedes"],
      "additionalProperties": false,
      "properties": {
        "superseded_by": {"type": ["string", "null"], "pattern": "^https://"},
        "supersedes": {"type": ["string", "null"], "pattern": "^https://"}
      }
    },
    "evidence": {"type": "array", "minItems": 1, "items": {"$ref": "#/definitions/url"}},
    "review": {
      "type": "object",
      "required": ["next_review_at", "outcome"],
      "additionalProperties": false,
      "properties": {
        "next_review_at": {"$ref": "#/definitions/date"},
        "outcome": {
          "oneOf": [
            {"type": "null"},
            {
              "type": "object",
              "required": ["remeasured_value", "same_method", "result", "url", "reviewed_on"],
              "additionalProperties": false,
              "properties": {
                "remeasured_value": {"type": "string", "minLength": 1, "pattern": "[0-9]"},
                "same_method": {"type": "boolean", "const": true},
                "result": {"type": "string", "enum": ["met", "partially-met", "not-met"]},
                "url": {"$ref": "#/definitions/url"},
                "reviewed_on": {"$ref": "#/definitions/date"}
              }
            }
          ]
        }
      }
    }
  }
}

output-contract.example:
{
  "rfc": {"id": "RFC-118", "title": "Checkout p95 latency under 1.2 s", "author": "swe:alice", "shared_on": "2026-05-29"},
  "owner": "swe:alice",
  "inputs": [
    {"name": "problem", "value": {
      "metric": "checkout p95 latency (Grafana checkout-overview, 7-day window)",
      "current_value": "2.4 s",
      "target_value": "1.2 s",
      "by_date": "2026-07-15",
      "statement": "Checkout p95 is 2.4 s over the last 7 days against a 1.2 s target; 18 percent of mobile sessions abandon on the payment step, and the abandonment correlates with latency above 2 s."
    }},
    {"name": "options", "value": [
      {"name": "precompute cart totals into the orders table (checkout_v2 behind a flag)", "chosen": true},
      {"name": "cache the pricing service responses in Redis for 60 s", "chosen": false, "rejection_reason": "cuts p95 to about 1.8 s in the spike test, short of the 1.2 s target; stale prices during promotions"},
      {"name": "do nothing / keep current behaviour", "chosen": false, "rejection_reason": "abandonment cost estimated at 40k per month at current traffic"}
    ]},
    {"name": "blast_radius", "value": {
      "items": [
        {"kind": "service", "name": "checkout-service", "owner": "swe:alice"},
        {"kind": "data-store", "name": "orders table (shared with billing-job)", "owner": "swe:olena"},
        {"kind": "api", "name": "mobile checkout API v3", "owner": "mobile:dmytro", "count": "18 percent of traffic, 2 API consumers"},
        {"kind": "scheduled-job", "name": "billing-job nightly reconciliation", "owner": "swe:olena"},
        {"kind": "user-segment", "name": "mobile checkout users", "owner": "product:maria", "count": "18 percent of sessions"}
      ],
      "schema_change": true,
      "public_api_change": false,
      "data_backfill": true,
      "third_party_change": false
    }},
    {"name": "rollback", "value": {
      "mechanism": "feature-flag-off",
      "execute_minutes": 1,
      "executor": "oncall:checkout",
      "staging_run": {"exercised": true, "url": "https://ci.example.com/runs/88412"},
      "points_of_no_return": [
        {"step": "backfill of orders.total_cents for historical rows", "pre_check": "row count of orders with NULL total_cents equals the count from the dry run within 0.1 percent"}
      ]
    }},
    {"name": "milestones", "value": [
      {"date": "2026-06-12", "increment": "orders.total_cents column added and backfilled in staging; query proves parity with computed totals", "ship": false},
      {"date": "2026-06-26", "increment": "checkout_v2 flag on for internal users; p95 visible on the dashboard", "ship": false},
      {"date": "2026-07-03", "increment": "flag on for 100 percent of mobile traffic; abandonment panel updated", "ship": true}
    ]},
    {"name": "status", "value": "accepted"},
    {"name": "decided_on", "value": "2026-06-05"},
    {"name": "reviewers", "value": [
      {"handle": "swe:olena", "commented": true},
      {"handle": "mobile:dmytro", "commented": true},
      {"handle": "product:maria", "commented": false}
    ]},
    {"name": "comment_deadline", "value": "2026-06-04"}
  ],
  "decision": "Precompute cart totals into the orders table behind the checkout_v2 flag and ship to mobile by 2026-07-03.",
  "supersession": {"superseded_by": null, "supersedes": null},
  "evidence": [
    "https://grafana.example.com/d/checkout-overview?from=now-7d&to=now",
    "https://ci.example.com/runs/88412",
    "https://github.com/acme/checkout/pull/2210"
  ],
  "review": {
    "next_review_at": "2026-08-07",
    "outcome": {"remeasured_value": "1.1 s", "same_method": true, "result": "met", "url": "https://grafana.example.com/d/checkout-overview?from=1785024000000&to=1785628800000", "reviewed_on": "2026-08-06"}
  }
}

{
  "rfc": {"id": "RFC-119", "title": "Move checkout to GraphQL", "author": "swe:bob", "shared_on": "2026-05-29"},
  "owner": "swe:bob",
  "inputs": [
    {"name": "problem", "value": {
      "metric": "checkout latency",
      "current_value": "slow",
      "target_value": "fast",
      "by_date": "2026-07-15",
      "statement": "We need to migrate to GraphQL so the mobile checkout stops being slow."
    }},
    {"name": "options", "value": [
      {"name": "move checkout to GraphQL", "chosen": true}
    ]},
    {"name": "blast_radius", "value": {
      "items": [{"kind": "service", "name": "checkout-service", "owner": "swe:bob"}],
      "schema_change": true,
      "public_api_change": true,
      "data_backfill": true,
      "third_party_change": false
    }},
    {"name": "rollback", "value": {
      "mechanism": "revert-pr",
      "execute_minutes": 5,
      "executor": "swe:bob",
      "staging_run": {"exercised": false, "reason": "revert is trivial"},
      "points_of_no_return": []
    }},
    {"name": "milestones", "value": [
      {"date": "2026-09-30", "increment": "launch", "ship": true}
    ]},
    {"name": "status", "value": "accepted"},
    {"name": "decided_on", "value": "2026-05-31"},
    {"name": "reviewers", "value": [{"handle": "team:backend", "commented": false}]},
    {"name": "comment_deadline", "value": "2026-05-30"}
  ],
  "decision": "Move to GraphQL. It will be faster and cleaner.",
  "supersession": {"superseded_by": null, "supersedes": null},
  "evidence": ["https://notion.example.com/rfc-119"],
  "review": {"next_review_at": "2027-01-15", "outcome": null}
}
